      const cv=document.createElement('canvas');cv.className='pilotSway';cv.width=cv.height=320;cv.setAttribute('aria-hidden','true');mark.appendChild(cv);pilotSway=null;
      const tmp=document.createElement('span');tmp.className='pilotSprite';tmp.dataset.pilot=id;tmp.dataset.state='NORMAL';tmp.hidden=true;document.body.appendChild(tmp);
