        if(!cv.isConnected)return;
        if(list.every(([,v])=>v.img)&&(pilotSway=createPilotLayers(cv,Object.fromEntries(list),rig)))return mark.classList.add('swayOn'),mark.classList.toggle('swayPatch',pilotSway.patched);
        return Promise.all([load(url),purl?load(purl):null]).then(([img,patch])=>{if(img&&cv.isConnected&&(pilotSway=createPilotSway(cv,img,rig,patch,rect)))mark.classList.add('swayOn'),mark.classList.toggle('swayPatch',pilotSway.patched);});
